// Responsive AVIF/WebP image from public/img (generated by scripts/images.py, described by src/data/images.json).
import images from '../data/images.json';

type ImageInfo = { width: number; height: number; widths: number[]; alpha: boolean };

const catalog = images as Record<string, ImageInfo>;

export function imageInfo(key: string): ImageInfo {
  const info = catalog[key];
  if (!info) throw new Error(`Unknown image "${key}"; run scripts/images.py`);
  return info;
}

export const imageUrl = (key: string, width: number, ext: 'avif' | 'webp') => `/img/${key}-${width}.${ext}`;

export function srcSet(key: string, ext: 'avif' | 'webp'): string {
  return imageInfo(key)
    .widths.map((w) => `${imageUrl(key, w, ext)} ${w}w`)
    .join(', ');
}

type Props = {
  image: string;
  alt: string;
  /** The `sizes` attribute: how wide the image is drawn at each viewport width. */
  sizes: string;
  className?: string;
  /** Above-the-fold image: load eagerly with high priority. */
  priority?: boolean;
  /**
   * Screenshots in ui/ are @2x captures; their natural CSS size is half their pixel size. Set false for images whose
   * pixel size is the intended display size.
   */
  retina?: boolean;
};

export default function Picture({ image, alt, sizes, className, priority = false, retina = true }: Props) {
  const info = imageInfo(image);
  const scale = retina ? 2 : 1;
  const largest = info.widths[info.widths.length - 1];
  return (
    <picture>
      <source type="image/avif" srcSet={srcSet(image, 'avif')} sizes={sizes} />
      <img
        src={imageUrl(image, largest, 'webp')}
        srcSet={srcSet(image, 'webp')}
        sizes={sizes}
        alt={alt}
        width={Math.round(info.width / scale)}
        height={Math.round(info.height / scale)}
        loading={priority ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : undefined}
        className={className}
      />
    </picture>
  );
}
